def build_prompt(card):
    """Build one complete prompt with the shared style applied exactly once."""
    return (
        STYLE_PROMPT.strip()
        + "\\n\\nLESSON: "
        + card["title"]
        + "\\n\\n"
        + card["prompt"].strip()
    )

def build_prompts(section=None, search=None):
    """Return full prompt strings, optionally filtered by section or title/content."""
    results = []
    needle = search.casefold() if search else None
    for card in CARD_DATA:
        if section and card["section"] != section:
            continue
        searchable = " ".join([
            card["title"], card["learning_goal"], card["visual_plan"], card["section"]
        ]).casefold()
        if needle and needle not in searchable:
            continue
        results.append(build_prompt(card))
    return results

def list_sections():
    counts = {}
    for card in CARD_DATA:
        counts[card["section"]] = counts.get(card["section"], 0) + 1
    for name, count in counts.items():
        print(f"{name}: {count} cards")
    print(f"TOTAL: {len(CARD_DATA)} cards")

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--section", help="Only generate prompts from this exact section ID.")
    parser.add_argument("--search", help="Filter cards by keyword in title, objective, visual plan, or section.")
    parser.add_argument("--format", choices=["json", "txt"], default="json")
    parser.add_argument("--output", help="Output file. If omitted, print to stdout.")
    parser.add_argument("--list-sections", action="store_true")
    args = parser.parse_args()

    if args.list_sections:
        list_sections()
        return

    selected = [
        card for card in CARD_DATA
        if (not args.section or card["section"] == args.section)
        and (not args.search or args.search.casefold() in
             " ".join([card["title"], card["learning_goal"], card["visual_plan"], card["section"]]).casefold())
    ]

    if args.format == "json":
        payload = [
            {**card, "full_prompt": build_prompt(card)}
            for card in selected
        ]
        output = json.dumps(payload, ensure_ascii=False, indent=2)
    else:
        output = "\\n\\n" + ("\\n\\n" + "=" * 88 + "\\n\\n").join(
            f"[{card['id']}] {card['section']}\\n{build_prompt(card)}"
            for card in selected
        )

    if args.output:
        path = Path(args.output)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(output.strip() + "\\n", encoding="utf-8")
        print(f"Wrote {len(selected)} prompts to {path}")
    else:
        print(output)

if __name__ == "__main__":
    main()
